import { parseArgs } from './args.ts';
import { createClient } from './client.ts';
import { resolveConfig } from './config.ts';
import { formatError, formatLookup, formatShorten, formatStats, usage } from './format.ts';
import { ApiError, type Config, type Deps } from './types.ts';

const message = (e: unknown) => (e instanceof Error ? e.message : String(e));

export async function main(argv: string[], deps: Deps): Promise<number> {
  const parsed = parseArgs(argv);
  if (!parsed.ok) {
    deps.err(`error: ${parsed.error}`);
    deps.err(usage());
    return 2;
  }
  const { command, server, json } = parsed.args;
  if (command.kind === 'help') {
    deps.out(usage());
    return 0;
  }
  let config: Config;
  try {
    config = resolveConfig(deps.env, { server, json });
  } catch (e) {
    deps.err(`error: ${message(e)}`);
    return 2;
  }
  const client = createClient(config.server, deps.fetch);
  const show = <T>(r: T, fmt: (r: T) => string) => deps.out(config.json ? JSON.stringify(r) : fmt(r));
  try {
    if (command.kind === 'shorten') show(await client.shorten(command.url), formatShorten);
    else if (command.kind === 'lookup') show(await client.lookup(command.code), formatLookup);
    else show(await client.stats(), formatStats);
    return 0;
  } catch (e) {
    deps.err(e instanceof ApiError ? formatError(e) : `error: ${message(e)}`);
    return 1;
  }
}
